     1→//! Rides management commands (list, export, recover).
     2→//!
     3→//! T052: CLI rides commands with IPC integration
     4→//! T053: Export with --format and --output flags
     5→//! T073: Recover subcommand for incomplete rides
     6→
     7→use clap::Subcommand;
