    15→/// Export format options
    16→#[derive(Debug, Clone, clap::ValueEnum)]
    17→pub enum ExportFormat {
    18→    /// FIT format (Garmin)
    19→    Fit,
    20→    /// TCX format (XML-based)
    21→    Tcx,
    22→    /// CSV format
    23→    Csv,
    24→}
    25→
    26→impl std::fmt::Display for ExportFormat {
    27→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    28→        match self {
    29→            ExportFormat::Fit => write!(f, "fit"),
    30→            ExportFormat::Tcx => write!(f, "tcx"),
    31→            ExportFormat::Csv => write!(f, "csv"),
    32→        }
    33→    }
    34→}
    35→
    36→/// Rides management subcommands
    37→#[derive(Debug, Subcommand)]
    38→pub enum RidesCommands {
    39→    /// List recorded rides
    40→    List {
    41→        /// Maximum number of rides to show
    42→        #[arg(long, short, default_value = "10")]
    43→        limit: usize,
    44→    },
    45→    /// Export a ride to file
    46→    Export {
    47→        /// Ride ID to export
    48→        ride_id: String,
    49→
    50→        /// T053: Output format
    51→        #[arg(long, short, value_enum, default_value = "fit")]
    52→        format: ExportFormat,
    53→
    54→        /// T053: Output file path (default: auto-generated)
    55→        #[arg(long, short)]
    56→        output: Option<PathBuf>,
    57→    },
    58→    /// T073: List incomplete rides that can be recovered
    59→    Incomplete,
    60→    /// T073: Recover an incomplete ride
    61→    Recover {
    62→        /// Ride ID to recover
    63→        ride_id: String,
    64→    },
    65→}
    66→
    67→/// Execute a rides subcommand
    68→pub async fn execute(cmd: RidesCommands) -> i32 {
    69→    match cmd {
    70→        RidesCommands::List { limit } => execute_list(limit).await,
    71→        RidesCommands::Export {
    72→            ride_id,
    73→            format,
    74→            output,
    75→        } => execute_export(ride_id, format, output).await,
    76→        RidesCommands::Incomplete => execute_incomplete().await,
    77→        RidesCommands::Recover { ride_id } => execute_recover(ride_id).await,
    78→    }
    79→}
    80→
    81→/// List rides
    82→async fn execute_list(limit: usize) -> i32 {
    83→    let socket_path = default_socket_path();
    84→
    85→    let request = IpcRequest::with_params(
    86→        "rides.list",
    87→        serde_json::json!({
    88→            "limit": limit
    89→        }),
    90→    );
    91→
    92→    match send_command(&socket_path, request).await {
    93→        Ok(response) => {
    94→            if response.success {
    95→                if is_json_output() {
    96→                    if let Some(result) = response.result {
    97→                        println!(
    98→                            "{}",
    99→                            serde_json::to_string_pretty(&result).unwrap_or_default()
   100→                        );
   101→                    }
   102→                } else if let Some(result) = &response.result {
   103→                    if let Some(rides) = result.get("rides").and_then(|v| v.as_array()) {
   104→if rides.is_empty() {
   105→                            println!("No rides recorded yet.");
   106→                        } else {
   107→                            println!("Recorded Rides");
   108→                            println!("==============");
   109→                            for ride in rides {
   110→                                let id = ride.get("id").and_then(|v| v.as_str()).unwrap_or("?");
   111→                                let date = ride.get("date").and_then(|v| v.as_str()).unwrap_or("?");
   112→                                let duration = ride
   113→                                    .get("duration_seconds")
   114→                                    .and_then(|v| v.as_u64())
   115→                                    .unwrap_or(0);
   116→                                let distance = ride
   117→                                    .get("distance_km")
   118→                                    .and_then(|v| v.as_f64())
   119→                                    .unwrap_or(0.0);
   120→
   121→                                let hours = duration / 3600;
   122→                                let minutes = (duration % 3600) / 60;
   123→
   124→                                println!(
   125→                                    "{} | {} | {}h {}m | {:.1} km",
   126→                                    id, date, hours, minutes, distance
   127→                                );
   128→                            }
   129→                        }
   130→                    }
   131→                }
   132→                exit_codes::SUCCESS
   133→            } else {
   134→                let error_msg = response
   135→                    .error
   136→                    .map(|e| e.message)
   137→                    .unwrap_or_else(|| "Unknown error".into());
   138→                if is_json_output() {
   139→                    println!(r#"{{"error": "{}"}}"#, error_msg);
   140→                } else {
   141→                    eprintln!("Error: {}", error_msg);
   142→                }
   143→                exit_codes::GENERAL_ERROR
   144→            }
   145→        }
   146→        Err(e) => {
   147→            if is_json_output() {
   148→                println!(r#"{{"error": "Failed to connect to daemon: {}"}}"#, e);
   149→            } else {
   150→                eprintln!("Failed to connect to daemon: {}", e);
   151→            }
   152→            exit_codes::DAEMON_NOT_RUNNING
   153→        }
   154→    }
   155→}
