   191→                    println!(r#"{{"error": "{}"}}"#, error_msg);
   192→                } else {
   193→                    eprintln!("Error: {}", error_msg);
   194→                }
   195→                exit_codes::GENERAL_ERROR
   196→            }
   197→        }
   198→        Err(e) => {
   199→            if is_json_output() {
   200→                println!(r#"{{"error": "Failed to connect to daemon: {}"}}"#, e);
   201→            } else {
   202→                eprintln!("Failed to connect to daemon: {}", e);
   203→            }
   204→            exit_codes::DAEMON_NOT_RUNNING
   205→        }
   206→    }
   207→}
