    89→
    90→    /// T108: Update sync status for a platform.
    91→    pub fn update_sync_status(&mut self, platform: SyncPlatform, status: SyncRecordStatus) {
    92→        if let Some(entry) = self.sync_status.iter_mut().find(|(p, _)| *p == platform) {
    93→            entry.1 = status;
    94→        } else {
    95→            self.sync_status.push((platform, status));
    96→        }
    97→    }
