    62→/// T032: Daemonize the process (fork to background)
    63→///
    64→/// This function performs the daemonization before the async runtime starts.
    65→/// It must be called before creating the tokio runtime.
    66→pub fn daemonize(config: &DaemonConfig) -> anyhow::Result<()> {
    67→    use std::fs::File;
    68→
    69→    info!("Daemonizing process...");
    70→
    71→    // Create PID file directory if needed
    72→    if let Some(parent) = config.pid_path.parent() {
    73→        std::fs::create_dir_all(parent)?;
    74→    }
    75→
    76→    // Setup daemonize with PID file
    77→    let mut daemonize = Daemonize::new()
    78→        .pid_file(&config.pid_path)
    79→        .chown_pid_file(true)
    80→        .working_directory("/");
    81→
    82→    // Redirect stdout/stderr to log file if specified
    83→    if let Some(ref log_path) = config.log_path {
    84→        // Create log file directory if needed
    85→        if let Some(parent) = log_path.parent() {
    86→            std::fs::create_dir_all(parent)?;
    87→        }
    88→        let stdout = File::create(log_path)?;
    89→        let stderr = stdout.try_clone()?;
    90→        daemonize = daemonize.stdout(stdout).stderr(stderr);
    91→    }
    92→
    93→    // Fork to background
    94→    match daemonize.start() {
    95→        Ok(_) => {
    96→            info!(
    97→                "Daemon forked to background, PID file: {:?}",
    98→                config.pid_path
    99→            );
   100→            Ok(())
   101→        }
   102→        Err(e) => {
   103→            error!("Failed to daemonize: {}", e);
   104→            anyhow::bail!("Failed to daemonize: {}", e)
   105→        }
   106→    }
   107→}
   108→
   109→/// Check if daemon is already running by checking PID file
   110→pub fn is_daemon_running(config: &DaemonConfig) -> bool {
   111→    if !config.pid_path.exists() {
   112→        return false;
   113→    }
   114→
   115→    // Read PID from file
   116→    if let Ok(pid_str) = std::fs::read_to_string(&config.pid_path) {
   117→        if let Ok(pid) = pid_str.trim().parse::<i32>() {
   118→            // Check if process is running using kill(pid, 0)
   119→            // This doesn't actually send a signal, just checks if process exists
   120→            unsafe {
   121→                if libc::kill(pid, 0) == 0 {
   122→                    return true;
   123→                }
   124→            }
   125→        }
   126→    }
   127→
   128→    // PID file exists but process not running - stale PID file
   129→    warn!("Removing stale PID file: {:?}", config.pid_path);
   130→    let _ = std::fs::remove_file(&config.pid_path);
   131→    false
   132→}
   133→
   134→/// Stop a running daemon by sending SIGTERM
   135→pub fn stop_daemon(config: &DaemonConfig) -> anyhow::Result<bool> {
   136→    if !config.pid_path.exists() {
   137→        return Ok(false);
   138→    }
   139→
   140→    // Read PID from file
   141→    let pid_str = std::fs::read_to_string(&config.pid_path)?;
   142→    let pid: i32 = pid_str.trim().parse()?;
   143→
   144→    // Send SIGTERM
   145→    unsafe {
   146→        if libc::kill(pid, libc::SIGTERM) == 0 {
   147→            info!("Sent SIGTERM to daemon PID {}", pid);
   148→            Ok(true)
   149→        } else {
   150→            // Process doesn't exist
   151→            warn!("Daemon process {} not found, removing stale PID file", pid);
   152→            let _ = std::fs::remove_file(&config.pid_path);
   153→            Ok(false)
   154→        }
   155→    }
   156→}
