     1→//! TCX export functionality for ride data.
     2→//!
     3→//! T095: Implement TCX XML structure generation with quick-xml
     4→//! T096: Include power data in TCX ActivityExtension/TPX
     5→
     6→use crate::recording::types::{ExportError, Ride, RideSample};
     7→use chrono::{DateTime, Duration, Utc};
     8→use quick_xml::events::{BytesDecl, BytesEnd, BytesStart, BytesText, Event};
     9→use quick_xml::Writer;
    10→use std::io::Cursor;
    11→
    12→/// TCX XML namespaces
    13→const NS_TCX: &str = "http://www.garmin.com/xmlschemas/TrainingCenterDatabase/v2";
    14→const NS_TPX: &str = "http://www.garmin.com/xmlschemas/ActivityExtension/v2";
    15→const NS_XSI: &str = "http://www.w3.org/2001/XMLSchema-instance";
    16→const SCHEMA_LOCATION: &str = "http://www.garmin.com/xmlschemas/TrainingCenterDatabase/v2 http://www.garmin.com/xmlschemas/TrainingCenterDatabasev2.xsd";
    17→
    18→/// Export a ride to TCX format.
    19→pub fn export_tcx(ride: &Ride, samples: &[RideSample]) -> Result<String, ExportError> {
    20→    if samples.is_empty() {
    21→        return Err(ExportError::NoData);
    22→    }
    23→
    24→    let mut writer = Writer::new_with_indent(Cursor::new(Vec::new()), b' ', 2);
    25→
    26→    // XML declaration
    27→    writer
    28→        .write_event(Event::Decl(BytesDecl::new("1.0", Some("UTF-8"), None)))
    29→        .map_err(|e| ExportError::XmlError(e.to_string()))?;
    30→
    31→    // Root element
    32→    let mut root = BytesStart::new("TrainingCenterDatabase");
    33→    root.push_attribute(("xmlns", NS_TCX));
    34→    root.push_attribute(("xmlns:ns3", NS_TPX));
    35→    root.push_attribute(("xmlns:xsi", NS_XSI));
    36→    root.push_attribute(("xsi:schemaLocation", SCHEMA_LOCATION));
    37→    writer
    38→        .write_event(Event::Start(root))
    39→        .map_err(|e| ExportError::XmlError(e.to_string()))?;
    40→
    41→    // Activities container
    42→    writer
    43→        .write_event(Event::Start(BytesStart::new("Activities")))
    44→        .map_err(|e| ExportError::XmlError(e.to_string()))?;
    45→
    46→    // Single Activity
    47→    let mut activity = BytesStart::new("Activity");
    48→    activity.push_attribute(("Sport", "Biking"));
    49→    writer
    50→        .write_event(Event::Start(activity))
    51→        .map_err(|e| ExportError::XmlError(e.to_string()))?;
    52→
    53→    // Activity Id (start time)
    54→    write_element(&mut writer, "Id", &ride.started_at.to_rfc3339())?;
    55→
    56→    // Write Lap(s) - for now, single lap for entire ride
    57→    write_lap(&mut writer, ride, samples)?;
    58→
    59→    // Close Activity
    60→    writer
    61→        .write_event(Event::End(BytesEnd::new("Activity")))
    62→        .map_err(|e| ExportError::XmlError(e.to_string()))?;
    63→
    64→    // Close Activities
    65→    writer
    66→        .write_event(Event::End(BytesEnd::new("Activities")))
    67→        .map_err(|e| ExportError::XmlError(e.to_string()))?;
    68→
    69→    // Close TrainingCenterDatabase
    70→    writer
    71→        .write_event(Event::End(BytesEnd::new("TrainingCenterDatabase")))
    72→        .map_err(|e| ExportError::XmlError(e.to_string()))?;
    73→
    74→    let result = writer.into_inner().into_inner();
    75→    String::from_utf8(result).map_err(|e| ExportError::XmlError(e.to_string()))
    76→}
