   179→                    current_index,
   180→                    end_index,
   181→                    ride_start_time,
   182→                ) {
   183→                    laps.push(lap);
   184→                }
   185→            }
   186→
   187→            current_index = end_index;
   188→            accumulated_duration = segment_end_time;
   189→
   190→            // Stop if we've processed all samples
   191→            if current_index >= samples.len() {
