   430→/// Export a ride to FIT format with cycling dynamics support.
   431→pub fn export_fit(ride: &Ride, samples: &[RideSample]) -> Result<Vec<u8>, ExportError> {
   432→    if samples.is_empty() {
   433→        return Err(ExportError::NoData);
   434→    }
   435→
   436→    let mut writer = FitWriter::new();
   437→
   438→    // Write FIT header
   439→    writer.write_header()?;
   440→
   441→    // Write File ID message
   442→    write_file_id(&mut writer, ride)?;
   443→
   444→    // Write File Creator message
   445→    write_file_creator(&mut writer)?;
   446→
   447→    // Write Event message (timer start)
   448→    write_event(&mut writer, ride.started_at, 0, 0)?; // timer start
   449→
   450→    // Check if any sample has dynamics data
   451→    let has_dynamics = samples.iter().any(|s| {
   452→        s.left_right_balance.is_some()
   453→            || s.left_torque_effectiveness.is_some()
   454→            || s.right_torque_effectiveness.is_some()
   455→            || s.left_pedal_smoothness.is_some()
   456→            || s.right_pedal_smoothness.is_some()
   457→    });
   458→
   459→    // T130: Check if any sample has power phase data
   460→    let has_power_phase = samples
   461→        .iter()
   462→        .any(|s| s.left_power_phase_start.is_some() || s.right_power_phase_start.is_some());
   463→
   464→    // Write Record messages for each sample
   465→    write_records(
   466→        &mut writer,
   467→        ride.started_at,
   468→        samples,
   469→        has_dynamics,
   470→        has_power_phase,
   471→    )?;
   472→
   473→    // Write Event message (timer stop)
   474→    let end_time = ride.ended_at.unwrap_or(ride.started_at);
   475→    write_event(&mut writer, end_time, 0, 1)?; // timer stop
   476→
   477→    // Write Lap message
   478→    write_lap(&mut writer, ride)?;
   479→
   480→    // Write Session message
   481→    write_session(&mut writer, ride)?;
   482→
   483→    // Write Activity message
   484→    write_activity(&mut writer, ride)?;
   485→
   486→    // Finalize and return
   487→    writer.finalize()
   488→}
   489→
   490→/// Write File ID message
   491→fn write_file_id(writer: &mut FitWriter, ride: &Ride) -> Result<(), ExportError> {
   492→    // Define File ID message (local message 0)
   493→    let fields = [
   494→        (0, 1, base_type::ENUM),   // type (activity = 4)
   495→        (1, 2, base_type::UINT16), // manufacturer
   496→        (2, 2, base_type::UINT16), // product
   497→        (3, 4, base_type::UINT32), // serial_number
   498→        (4, 4, base_type::UINT32), // time_created
   499→    ];
   500→    writer.write_definition(0, message_type::FILE_ID, &fields)?;
   501→
   502→    // Write File ID data
   503→    writer.write_data_header(0)?;
   504→    writer.write_byte(4)?; // type = activity
   505→    writer.write_u16(1)?; // manufacturer = Garmin (for compatibility)
   506→    writer.write_u16(1)?; // product
   507→    writer.write_u32(1)?; // serial_number
   508→    writer.write_u32(FitWriter::datetime_to_fit_timestamp(ride.started_at))?;
   509→
   510→    Ok(())
   511→}
   512→
   513→/// Write File Creator message
   514→fn write_file_creator(writer: &mut FitWriter) -> Result<(), ExportError> {
   515→    let fields = [
   516→        (0, 2, base_type::UINT16), // software_version
   517→    ];
   518→    writer.write_definition(1, message_type::FILE_CREATOR, &fields)?;
   519→

