   938→/// Write Activity message
   939→fn write_activity(writer: &mut FitWriter, ride: &Ride) -> Result<(), ExportError> {
   940→    let fields = [
   941→        (field_type::TIMESTAMP, 4, base_type::UINT32), // timestamp
   942→        (0, 4, base_type::UINT32),                     // total_timer_time
   943→        (1, 2, base_type::UINT16),                     // num_sessions
   944→        (2, 1, base_type::ENUM),                       // type (manual = 0)
   945→        (3, 1, base_type::ENUM),                       // event (activity = 26)
   946→        (4, 1, base_type::ENUM),                       // event_type (stop = 1)
   947→        (5, 4, base_type::UINT32),                     // local_timestamp
   948→    ];
   949→    writer.write_definition(6, message_type::ACTIVITY, &fields)?;
   950→
   951→    let end_time = ride.ended_at.unwrap_or(ride.started_at);
   952→    let total_time_ms = ride.duration_seconds * 1000;
   953→
   954→    writer.write_data_header(6)?;
   955→    writer.write_u32(FitWriter::datetime_to_fit_timestamp(end_time))?;
   956→    writer.write_u32(total_time_ms)?;
   957→    writer.write_u16(1)?; // num_sessions = 1
   958→    writer.write_byte(0)?; // type = manual
   959→    writer.write_byte(26)?; // event = activity
   960→    writer.write_byte(1)?; // event_type = stop
   961→    writer.write_u32(FitWriter::datetime_to_fit_timestamp(end_time))?;
   962→
   963→    Ok(())
   964→}
