   966→/// Export a ride to FIT and write to a file.
   967→pub fn export_fit_to_file(
   968→    ride: &Ride,
   969→    samples: &[RideSample],
   970→    path: &std::path::Path,
   971→) -> Result<(), ExportError> {
   972→    let content = export_fit(ride, samples)?;
   973→    std::fs::write(path, content)?;
   974→    Ok(())
   975→}
