   317→    /// Write a definition message
   318→    fn write_definition(
   319→        &mut self,
   320→        local_mesg_num: u8,
   321→        global_mesg_num: u16,
   322→        fields: &[(u8, u8, u8)], // (field_def_num, size, base_type)
   323→    ) -> Result<(), ExportError> {
   324→        // Record header: definition message (bit 6 set), local message num in bits 0-3
   325→        let header = 0x40 | (local_mesg_num & 0x0F);
   326→        self.write_byte(header)?;
   327→
   328→        // Reserved byte
   329→        self.write_byte(0)?;
   330→
   331→        // Architecture: 0 = little endian
   332→        self.write_byte(0)?;
   333→
   334→        // Global message number (little endian)
   335→        self.write_u16(global_mesg_num)?;
   336→
   337→        // Number of fields
   338→        self.write_byte(fields.len() as u8)?;
   339→
   340→        // Field definitions
   341→        for (field_num, size, base_type) in fields {
   342→            self.write_byte(*field_num)?;
   343→            self.write_byte(*size)?;
   344→            self.write_byte(*base_type)?;
   345→        }
   346→
   347→        Ok(())
   348→    }
   349→
   350→    /// Write a data message header
