   394→    /// Finalize the file (update data size and append CRC)
   395→    fn finalize(self) -> Result<Vec<u8>, ExportError> {
   396→        let data_size = self.data_size;
   397→        let mut data = self.buffer.into_inner();
   398→
   399→        // Update data size in header (bytes 4-7)
   400→        let data_size_bytes = data_size.to_le_bytes();
   401→        data[4..8].copy_from_slice(&data_size_bytes);
   402→
   403→        // Calculate CRC for the entire file (excluding the final CRC itself)
   404→        let file_crc = calculate_crc(&data[..]);
   405→        data.extend_from_slice(&file_crc.to_le_bytes());
   406→
   407→        Ok(data)
   408→    }
   409→}
