   411→/// Calculate CRC-16 for FIT file (standalone function)
   412→fn calculate_crc(data: &[u8]) -> u16 {
   413→    let mut crc: u16 = 0;
   414→    let crc_table: [u16; 16] = [
   415→        0x0000, 0xCC01, 0xD801, 0x1400, 0xF001, 0x3C00, 0x2800, 0xE401, 0xA001, 0x6C00, 0x7800,
   416→        0xB401, 0x5000, 0x9C01, 0x8801, 0x4400,
   417→    ];
   418→
   419→    for byte in data {
   420→        let tmp = crc_table[(crc & 0xF) as usize];
   421→        crc = (crc >> 4) & 0x0FFF;
   422→        crc = crc ^ tmp ^ crc_table[(*byte & 0xF) as usize];
   423→
   424→        let tmp = crc_table[(crc & 0xF) as usize];
   425→        crc = (crc >> 4) & 0x0FFF;
   426→        crc = crc ^ tmp ^ crc_table[((*byte >> 4) & 0xF) as usize];
   427→    }
   428→
   429→    crc
   430→}
